import type { PaneDirection, PaneNode } from "../state/paneTree";

export type WorktreeIdentity = {
  wsId: string;
  slug: string;
};

export type Worktree = {
  path: string;
  head: string;
  branch: string | null;
  bare: boolean;
  detached: boolean;
  locked: string | null;
  prunable: string | null;
};

export function worktreeIdentity(worktree: Worktree): WorktreeIdentity | null {
  const branch = worktree.branch?.replace(/^refs\/heads\//, "");
  const parts = branch?.split("/");
  if (!parts || parts.length < 3 || parts[0] !== "orca") return null;

  return { wsId: parts[1], slug: parts.slice(2).join("/") };
}

export type DirtyFile = {
  statusCode: string;
  path: string;
};

export type DirtyState = {
  isDirty: boolean;
  files: DirtyFile[];
};

export type BranchDeletionPreview = {
  branch: string;
  head: string;
  upstream: string | null;
  merged: boolean;
  ahead: number | null;
  behind: number | null;
};

export type TerminalSignal = "interrupt" | "terminate" | "kill";

export type TerminalSessionSummary = {
  sessionId: string;
  worktreePath: string | null;
};

export type TerminalLifecycle = "starting" | "working" | "waiting" | "exited" | "failed";

export type TerminalSession = {
  /** Frontend-local stable identity used by pane leaves and terminal renderer ownership. */
  id: string;
  /** Best known process CWD. It may be nested below the worktree root after `cd`. */
  cwd: string;
  /** Stable worktree/repository root. Optional only for v1/test-state compatibility. */
  worktreePath?: string;
  workspaceId: string;
  worktree: WorktreeIdentity | null;
  /** Native PTY identity. This is intentionally distinct from `id`. */
  backendSessionId: string | null;
  lifecycle: TerminalLifecycle;
  ownerId?: string | null;
};

export type TerminalTab = {
  kind?: "terminal";
  id: string;
  label: string;
  /** Compatibility primary session; every real pane leaf is authoritative in TabPaneLayout. */
  sessionId: string;
  pinned?: boolean;
};

export type BrowserProfileId = "default" | "private";

export type LogicalRect = {
  x: number;
  y: number;
  width: number;
  height: number;
};

export type BrowserState = {
  browserId: string;
  webviewLabel: string;
  workspaceId?: string | null;
  worktreePath?: string | null;
  profileId: BrowserProfileId;
  generation: number;
  url: string;
  title?: string | null;
  loading: boolean;
  canGoBack: boolean;
  canGoForward: boolean;
  zoomFactor: number;
  loadError?: string | null;
  visible: boolean;
};

export type BrowserTab = {
  kind: "browser";
  id: string;
  label: string;
  browserId: string;
  url: string;
  title?: string | null;
  loading?: boolean;
  canGoBack?: boolean;
  canGoForward?: boolean;
  profileId?: string;
  worktreePath?: string;
  worktreeLabel?: string;
  pinned?: boolean;
};

export type WorkspaceTab = TerminalTab | BrowserTab;

export type CreateBrowserRequest = {
  workspaceId?: string | null;
  worktreePath?: string | null;
  url: string;
  profile?: BrowserProfileId;
  bounds?: LogicalRect;
  visible?: boolean;
};

export type BrowserSessionSummary = {
  browserId: string;
  webviewLabel: string;
  workspaceId?: string | null;
  profileId?: string | null;
  url: string;
  title?: string | null;
  visible: boolean;
};

export type Pane = {
  id: string;
  tabId: string;
};

export type SplitMode = "none" | "horizontal" | "vertical";

export type NestedSplit = {
  orientation: Exclude<SplitMode, "none">;
  tabId: string;
};

/**
 * The split arrangement inside a single terminal tab. This is intentionally separate
 * from TabGroupLayoutNode: Orca keeps terminal panes inside a tab and split tab groups
 * as two different layout layers.
 */
export type TabPaneLayout = {
  root: PaneNode;
  /** Leaf that receives keyboard focus inside this tab. */
  activeLeafId: string | null;
  /** Leaf temporarily zoomed to fill the tab, or `null` when every pane is visible. */
  expandedLeafId: string | null;
  /** Frontend-local terminal session rendered by each leaf of `root`. */
  sessionIdsByLeafId: Record<string, string>;
};

export type TabGroup = {
  id: string;
  tabIds: string[];
  activeTabId: string | null;
};

export type TabGroupLayoutNode =
  | { type: "group"; groupId: string }
  | {
      type: "split";
      direction: PaneDirection;
      first: TabGroupLayoutNode;
      second: TabGroupLayoutNode;
      ratio: number;
    };

export type LayoutState = {
  tabs: WorkspaceTab[];
  primaryTabId?: string | null;
  secondaryTabId?: string | null;
  split?: SplitMode;
  nestedSplit?: NestedSplit | null;
  /** Active tab in the currently focused tab group. */
  activeTabId: string | null;
  /** Terminal-pane tree owned independently by each tab. */
  layoutsByTabId: Record<string, TabPaneLayout>;
  /** Orca-style tab groups. Optional only for backwards-compatible persisted/test state. */
  tabGroups?: Record<string, TabGroup>;
  /** Split tree whose leaves are tab groups, not terminal panes. */
  tabGroupLayout?: TabGroupLayoutNode | null;
  focusedGroupId?: string | null;
};

export type AgentState = "starting" | "working" | "waiting" | "exited" | "failed";

export type ActiveAgent = {
  id: string;
  name: string;
  task: string;
  state: AgentState;
  worktree: WorktreeIdentity | null;
  worktreePath: string;
  sessionId: string;
};

export type TerminalOutputPayload = {
  sessionId: string;
  data: string;
};

export type TerminalLifecyclePayload = {
  sessionId: string;
  state: "started" | "exited" | "failed";
  exitCode: number | null;
  reason: string | null;
};

export type WorktreeChangedPayload = {
  workspaceId: string;
  worktree: WorktreeIdentity;
  kind: "created" | "deleted" | "destructivelyDeleted" | "dirtyChanged" | "pruned";
};

export type NotificationSource = "agent-task-complete" | "terminal-bell" | "system";
export type NotificationAuthorization = "not-determined" | "denied" | "authorized" | "provisional" | "unknown";
export type NotificationPlatform = "macos" | "windows" | "linux" | "unknown";

export interface NotificationPermissionStatus {
  platform?: NotificationPlatform;
  supported?: boolean;
  authorization: NotificationAuthorization;
  alertsEnabled?: boolean | null;
  soundsEnabled?: boolean | null;
  requested?: boolean;
  authoritative?: boolean;
  canOpenSettings?: boolean;
  status?: string;
}

export interface NotificationPermissionRequest {
  granted: boolean;
  status?: NotificationPermissionStatus;
  error?: string | null;
}

export interface DispatchNotificationArgs {
  source?: NotificationSource | string;
  title?: string;
  body?: string;
  notificationId?: string;
  workspaceLabel?: string;
  worktreeLabel?: string;
  terminalTitle?: string;
  agentLabel?: string;
}

export interface DispatchNotificationResult {
  submitted?: boolean;
  delivered?: boolean;
  reason?: "permission-required" | "blocked-by-system" | "unsupported" | "backend-error" | string;
}

export interface NotificationProbeResult {
  outcome?: "submitted" | "ready" | "permission-required" | "blocked-by-system" | "unsupported" | "failed" | string;
  status?: NotificationPermissionStatus;
  testSubmitted?: boolean;
  success?: boolean;
}

export interface OpenSystemSettingsResult {
  opened: boolean;
  reason?: string | null;
}

export interface PlaySoundResult {
  played: boolean;
  reason?: string | null;
}

export interface PickedAudioFile {
  path: string;
  displayName?: string;
  extension?: string;
  sizeBytes?: number;
}

export type StructuredIpcError = {
  code: string;
  message: string;
  details?: Record<string, unknown>;
};

export interface PersistedWorktree {
  path: string;
  branch: string;
  head: string;
  isMain: boolean;
  isLocked: boolean;
}

/** Version-2 terminal tab payload. All IDs in pane mappings are frontend-local session IDs. */
export interface PersistedTerminalTabState {
  primarySessionId: string;
  paneTree: PaneNode;
  sessionIdsByLeafId: Record<string, string>;
  activeLeafId: string | null;
  expandedLeafId: string | null;
}

export interface PersistedBrowserTabState {
  browserId: string;
  url: string;
  title?: string | null;
  loading?: boolean;
  canGoBack?: boolean;
  canGoForward?: boolean;
  profileId?: string;
  worktreePath?: string;
  worktreeLabel?: string;
}

/**
 * Version-2 tab record. Legacy v1 fields remain optional so persisted sessions can be
 * migrated in place without unsafe casts or a second DTO hierarchy.
 */
export interface PersistedTab {
  id: string;
  label: string;
  kind?: "terminal" | "browser";
  pinned?: boolean;
  terminal?: PersistedTerminalTabState;
  browser?: PersistedBrowserTabState;
  customTitle?: string;

  // v1 compatibility fields
  sessionId?: string;
  worktreePath?: string;
  paneTree?: PaneNode;
  sessionIdsByLeafId?: Record<string, string>;
  activeLeafId?: string | null;
  expandedLeafId?: string | null;
}

export interface PersistedTabGroup {
  id: string;
  tabIds: string[];
  activeTabId: string | null;
}

export interface PersistedLayout {
  splitMode: string;
  primaryTabId: string | null;
  secondaryTabId: string | null;
  activeTabId: string | null;
  tabs: PersistedTab[];
  tabGroups?: PersistedTabGroup[];
  tabGroupLayout?: TabGroupLayoutNode | null;
  focusedGroupId?: string | null;
  layoutsByTabId?: Record<string, TabPaneLayout>;
}

export interface PersistedTerminalSession {
  /** v2 stable frontend identity; map key remains authoritative. */
  localSessionId?: string;
  /** v2 native PTY identity. `null` means it must be respawned on restore. */
  backendSessionId?: string | null;
  /** v1 compatibility field (v1 accidentally stored the local id here). */
  sessionId?: string;
  worktreePath: string;
  cwd: string;
  lastCommand?: string;
  recentScrollback?: string;
  createdAt: number;
}

export interface PersistedWorkspace {
  workspaceId: string;
  repoRoot: string;
  worktrees: PersistedWorktree[];
  activeWorktreePath: string | null;
  layout: PersistedLayout;
  worktreeLayouts?: Record<string, PersistedLayout>;
  terminalSessions: Record<string, PersistedTerminalSession>;
}

export interface PersistedWorkspaceSession {
  version: number;
  timestamp: number;
  activeWorkspaceId: string;
  workspaces: Record<string, PersistedWorkspace>;
}

export type PaneDirection = "horizontal" | "vertical";

export type PaneLeafNode = { type: "leaf"; leafId: string };

export type PaneSplitNode = {
  type: "split";
  direction: PaneDirection;
  first: PaneNode;
  second: PaneNode;
  ratio: number;
};

export type PaneNode = PaneLeafNode | PaneSplitNode;

export const MIN_PANE_RATIO = 0.1;
export const MAX_PANE_RATIO = 0.9;

/** Clamps a ratio into the usable range, falling back to an even split for non-finite input. */
export function clampRatio(ratio: number): number {
  if (!Number.isFinite(ratio)) return 0.5;
  return Math.min(MAX_PANE_RATIO, Math.max(MIN_PANE_RATIO, ratio));
}

export function createLeafNode(leafId?: string): PaneNode {
  return { type: "leaf", leafId: leafId ?? createLeafId() };
}

/**
 * Replaces the leaf `targetLeafId` with a split containing that leaf and a new leaf.
 * `position` decides which side the new leaf takes. Returns the original tree when
 * the target leaf does not exist.
 */
export function splitLeaf(
  root: PaneNode,
  targetLeafId: string,
  newLeafId: string,
  direction: PaneDirection,
  position: "first" | "second" = "second",
  ratio = 0.5,
): PaneNode {
  return splitLeafWithSubtree(root, targetLeafId, createLeafNode(newLeafId), direction, position, ratio);
}

/**
 * Replaces `targetLeafId` with a split containing the existing target leaf and an
 * arbitrary pane subtree. This is the pane-tree equivalent of Orca moving a whole
 * tab (including any terminal panes owned by that tab) into a newly-created split group.
 */
export function splitLeafWithSubtree(
  root: PaneNode,
  targetLeafId: string,
  subtree: PaneNode,
  direction: PaneDirection,
  position: "first" | "second" = "second",
  ratio = 0.5,
): PaneNode {
  return mapLeaf(root, targetLeafId, (leaf) => ({
    type: "split",
    direction,
    first: position === "first" ? subtree : leaf,
    second: position === "first" ? leaf : subtree,
    ratio: clampRatio(ratio),
  }));
}

/**
 * Removes the leaf `targetLeafId`, collapsing its parent split into the surviving sibling.
 * Returns `null` when the removed leaf was the whole tree, and the original tree when the
 * leaf does not exist.
 */
export function removeLeaf(root: PaneNode, targetLeafId: string): PaneNode | null {
  if (root.type === "leaf") return root.leafId === targetLeafId ? null : root;

  const first = removeLeaf(root.first, targetLeafId);
  if (first === null) return root.second;
  if (first !== root.first) return { ...root, first };

  const second = removeLeaf(root.second, targetLeafId);
  if (second === null) return root.first;
  if (second !== root.second) return { ...root, second };

  return root;
}

/**
 * Sets the ratio of the split addressed by a dot-notation `path` such as "" (root),
 * "first", or "second.first". Returns the original tree when the path does not resolve
 * to a split node.
 */
export function setRatioAtPath(root: PaneNode, path: string, ratio: number): PaneNode {
  const segments = path.split(".").filter((segment) => segment.length > 0);
  return applyRatio(root, segments, clampRatio(ratio));
}

export function findFirstLeafId(root: PaneNode): string {
  let node = root;
  while (node.type === "split") node = node.first;
  return node.leafId;
}

export function collectLeafIds(root: PaneNode): string[] {
  const ids: string[] = [];
  const visit = (node: PaneNode) => {
    if (node.type === "leaf") {
      ids.push(node.leafId);
      return;
    }
    visit(node.first);
    visit(node.second);
  };
  visit(root);
  return ids;
}

/**
 * Returns the first leaf id inside the sibling subtree of `targetLeafId`,
 * or `null` when the leaf is missing or is the tree root.
 */
export function findSiblingLeafId(root: PaneNode, targetLeafId: string): string | null {
  if (root.type === "leaf") return null;

  const inFirst = containsLeaf(root.first, targetLeafId);
  const inSecond = containsLeaf(root.second, targetLeafId);

  if (inFirst) {
    return root.first.type === "leaf"
      ? findFirstLeafId(root.second)
      : findSiblingLeafId(root.first, targetLeafId);
  }
  if (inSecond) {
    return root.second.type === "leaf"
      ? findFirstLeafId(root.first)
      : findSiblingLeafId(root.second, targetLeafId);
  }
  return null;
}

/**
 * Swaps the positions of two leaves. Returns the original tree when either leaf is
 * missing or when both ids refer to the same leaf.
 */
export function swapLeaves(root: PaneNode, sourceLeafId: string, targetLeafId: string): PaneNode {
  if (sourceLeafId === targetLeafId) return root;
  if (!containsLeaf(root, sourceLeafId) || !containsLeaf(root, targetLeafId)) return root;

  const swap = (node: PaneNode): PaneNode => {
    if (node.type === "leaf") {
      if (node.leafId === sourceLeafId) return { type: "leaf", leafId: targetLeafId };
      if (node.leafId === targetLeafId) return { type: "leaf", leafId: sourceLeafId };
      return node;
    }
    const first = swap(node.first);
    const second = swap(node.second);
    if (first === node.first && second === node.second) return node;
    return { ...node, first, second };
  };

  return swap(root);
}

/** Resets every split in the tree to an even 0.5 ratio. */
export function equalizeRatios(root: PaneNode): PaneNode {
  if (root.type === "leaf") return root;
  const first = equalizeRatios(root.first);
  const second = equalizeRatios(root.second);
  if (first === root.first && second === root.second && root.ratio === 0.5) return root;
  return { ...root, first, second, ratio: 0.5 };
}

function applyRatio(node: PaneNode, segments: string[], ratio: number): PaneNode {
  if (node.type === "leaf") return node;

  if (segments.length === 0) {
    return node.ratio === ratio ? node : { ...node, ratio };
  }

  const [head, ...rest] = segments;
  if (head !== "first" && head !== "second") return node;

  const child = applyRatio(node[head], rest, ratio);
  if (child === node[head]) return node;
  return { ...node, [head]: child };
}

function mapLeaf(node: PaneNode, targetLeafId: string, replace: (leaf: PaneLeafNode) => PaneNode): PaneNode {
  if (node.type === "leaf") return node.leafId === targetLeafId ? replace(node) : node;

  const first = mapLeaf(node.first, targetLeafId, replace);
  if (first !== node.first) return { ...node, first };

  const second = mapLeaf(node.second, targetLeafId, replace);
  if (second !== node.second) return { ...node, second };

  return node;
}

function containsLeaf(node: PaneNode, leafId: string): boolean {
  if (node.type === "leaf") return node.leafId === leafId;
  return containsLeaf(node.first, leafId) || containsLeaf(node.second, leafId);
}

function createLeafId() {
  const randomPart = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `pane:${randomPart}`;
}

import type { LayoutState, TabGroup, TabGroupLayoutNode, TabPaneLayout } from "../lib/types";
import { normalizeLayout } from "./layout";
import {
  collectLeafIds,
  findFirstLeafId,
  splitLeafWithSubtree,
  type PaneDirection,
  type PaneNode,
} from "./paneTree";

export type TabPaneDropTarget = {
  tabId: string;
  leafId: string;
};

/**
 * Moves a terminal tab's existing pane subtree into a specific leaf of another
 * terminal tab. No terminal session is created or destroyed: ownership moves
 * entirely inside the layout graph so xterm buffers and native PTYs survive.
 */
export function moveTabIntoPaneSplit(
  inputLayout: LayoutState,
  sourceTabId: string,
  targetTabId: string,
  targetLeafId: string,
  direction: PaneDirection,
  position: "first" | "second" = "second",
  ratio = 0.5,
): LayoutState {
  const state = normalizeLayout(inputLayout);
  if (sourceTabId === targetTabId) return state;

  const sourceTab = state.tabs.find((tab) => tab.id === sourceTabId);
  const targetTab = state.tabs.find((tab) => tab.id === targetTabId);
  const sourceLayout = state.layoutsByTabId[sourceTabId];
  const targetLayout = state.layoutsByTabId[targetTabId];
  if (
    !sourceTab ||
    !targetTab ||
    sourceTab.kind === "browser" ||
    targetTab.kind === "browser" ||
    !sourceLayout ||
    !targetLayout
  ) {
    return state;
  }

  const targetLeafIds = collectLeafIds(targetLayout.root);
  if (!targetLeafIds.includes(targetLeafId)) return state;

  const groups = { ...(state.tabGroups ?? {}) };
  const sourceGroup = findGroupContainingTab(groups, sourceTabId);
  const targetGroup = findGroupContainingTab(groups, targetTabId);
  if (!sourceGroup || !targetGroup) return state;

  // Legacy layouts can give every tab the same leaf id (for example `leaf-init`).
  // Remap only colliding source ids before the subtree is inserted so the combined
  // tree has a one-to-one leaf -> local session mapping.
  const moved = remapPaneLayout(sourceLayout, new Set(targetLeafIds));
  const nextTargetRoot = splitLeafWithSubtree(
    targetLayout.root,
    targetLeafId,
    moved.root,
    direction,
    position,
    ratio,
  );
  if (nextTargetRoot === targetLayout.root) return state;

  let tabGroupLayout = state.tabGroupLayout ?? null;
  const sourceIndex = sourceGroup.tabIds.indexOf(sourceTabId);
  const remainingSourceTabIds = sourceGroup.tabIds.filter((tabId) => tabId !== sourceTabId);
  if (remainingSourceTabIds.length === 0) {
    delete groups[sourceGroup.id];
    tabGroupLayout = removeTabGroupLeaf(tabGroupLayout, sourceGroup.id);
  } else {
    groups[sourceGroup.id] = {
      ...sourceGroup,
      tabIds: remainingSourceTabIds,
      activeTabId:
        sourceGroup.activeTabId === sourceTabId || !remainingSourceTabIds.includes(sourceGroup.activeTabId ?? "")
          ? remainingSourceTabIds[Math.min(sourceIndex, remainingSourceTabIds.length - 1)] ?? remainingSourceTabIds[0]
          : sourceGroup.activeTabId,
    };
  }

  const liveTargetGroup = groups[targetGroup.id];
  if (!liveTargetGroup) return state;
  groups[targetGroup.id] = { ...liveTargetGroup, activeTabId: targetTabId };

  const layoutsByTabId = { ...state.layoutsByTabId };
  delete layoutsByTabId[sourceTabId];
  layoutsByTabId[targetTabId] = {
    ...targetLayout,
    root: nextTargetRoot,
    activeLeafId: moved.activeLeafId ?? findFirstLeafId(moved.root),
    expandedLeafId: null,
    sessionIdsByLeafId: {
      ...targetLayout.sessionIdsByLeafId,
      ...moved.sessionIdsByLeafId,
    },
  };

  return normalizeLayout({
    ...state,
    tabs: state.tabs.filter((tab) => tab.id !== sourceTabId),
    activeTabId: targetTabId,
    focusedGroupId: targetGroup.id,
    tabGroups: groups,
    tabGroupLayout,
    layoutsByTabId,
  });
}

function remapPaneLayout(layout: TabPaneLayout, reservedLeafIds: Set<string>): TabPaneLayout {
  const leafIdMap = new Map<string, string>();
  const visit = (node: PaneNode): PaneNode => {
    if (node.type === "leaf") {
      let nextLeafId = node.leafId;
      while (reservedLeafIds.has(nextLeafId)) nextLeafId = createMovedLeafId();
      reservedLeafIds.add(nextLeafId);
      leafIdMap.set(node.leafId, nextLeafId);
      return nextLeafId === node.leafId ? node : { ...node, leafId: nextLeafId };
    }

    const first = visit(node.first);
    const second = visit(node.second);
    return first === node.first && second === node.second ? node : { ...node, first, second };
  };

  const root = visit(layout.root);
  const sessionIdsByLeafId: Record<string, string> = {};
  for (const [leafId, sessionId] of Object.entries(layout.sessionIdsByLeafId)) {
    sessionIdsByLeafId[leafIdMap.get(leafId) ?? leafId] = sessionId;
  }

  return {
    root,
    activeLeafId: layout.activeLeafId ? (leafIdMap.get(layout.activeLeafId) ?? layout.activeLeafId) : null,
    expandedLeafId: layout.expandedLeafId ? (leafIdMap.get(layout.expandedLeafId) ?? layout.expandedLeafId) : null,
    sessionIdsByLeafId,
  };
}

function findGroupContainingTab(groups: Record<string, TabGroup>, tabId: string): TabGroup | null {
  return Object.values(groups).find((group) => group.tabIds.includes(tabId)) ?? null;
}

function removeTabGroupLeaf(root: TabGroupLayoutNode | null, groupId: string): TabGroupLayoutNode | null {
  if (!root) return null;
  if (root.type === "group") return root.groupId === groupId ? null : root;

  const first = removeTabGroupLeaf(root.first, groupId);
  if (!first) return root.second;
  if (first !== root.first) return { ...root, first };

  const second = removeTabGroupLeaf(root.second, groupId);
  if (!second) return root.first;
  if (second !== root.second) return { ...root, second };
  return root;
}

function createMovedLeafId(): string {
  const randomPart = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `leaf:moved:${randomPart}`;
}

import type {
  LayoutState,
  TabGroup,
  TabGroupLayoutNode,
  TabPaneLayout,
  WorkspaceTab,
} from "../lib/types";
import {
  clampRatio,
  collectLeafIds,
  createLeafNode,
  equalizeRatios,
  findFirstLeafId,
  findSiblingLeafId,
  type PaneDirection,
  removeLeaf,
  setRatioAtPath,
  splitLeaf,
  swapLeaves,
} from "./paneTree";

export type LayoutAction =
  | { type: "ADD_TAB"; tab: WorkspaceTab; sessionId?: string; activate?: boolean }
  | { type: "CLOSE_TAB"; tabId: string; replacementTab?: WorkspaceTab }
  | { type: "ACTIVATE_TAB"; tabId: string }
  | { type: "REORDER_TAB"; tabId: string; targetIndex: number }
  | { type: "RENAME_TAB"; tabId: string; label: string }
  | { type: "SET_TAB_PINNED"; tabId: string; pinned: boolean }
  | {
      type: "SPLIT_PANE";
      tabId: string;
      targetLeafId?: string;
      direction: PaneDirection;
      newLeafId?: string;
      sessionId: string;
      position?: "first" | "second";
      ratio?: number;
    }
  | {
      type: "MOVE_TAB_TO_GROUP";
      sourceTabId: string;
      targetGroupId: string;
      targetIndex?: number;
    }
  | {
      type: "MOVE_TAB_TO_SPLIT";
      sourceTabId: string;
      targetGroupId: string;
      direction: PaneDirection;
      position?: "first" | "second";
      ratio?: number;
    }
  | {
      type: "DETACH_PANE_TO_TAB";
      sourceTabId: string;
      leafId: string;
      newTab: WorkspaceTab;
      targetGroupId?: string;
      targetIndex?: number;
    }
  | { type: "SET_TAB_GROUP_RATIO"; path: string; ratio: number }
  | { type: "CLOSE_PANE"; tabId: string; leafId: string; replacementSessionId?: string }
  | { type: "FOCUS_PANE"; tabId: string; leafId: string }
  | { type: "SET_PANE_RATIO"; tabId: string; path: string; ratio: number }
  | { type: "SWAP_PANES"; tabId: string; sourceLeafId: string; targetLeafId: string }
  | { type: "TOGGLE_PANE_EXPANDED"; tabId: string; leafId: string }
  | { type: "EQUALIZE_PANES"; tabId: string };

export function createLayoutState(tabs: WorkspaceTab[] = [], activeTabId?: string | null): LayoutState {
  const layoutsByTabId: Record<string, TabPaneLayout> = {};
  for (const tab of tabs) {
    const leafId = "leaf-init";
    const sessionId = tab.kind === "browser" ? "" : tab.sessionId;
    layoutsByTabId[tab.id] = {
      root: createLeafNode(leafId),
      activeLeafId: leafId,
      expandedLeafId: null,
      sessionIdsByLeafId: { [leafId]: sessionId },
    };
  }

  return normalizeLayoutInternal(
    {
      tabs,
      activeTabId: activeTabId ?? tabs[0]?.id ?? null,
      layoutsByTabId,
    },
    true,
  );
}

export function getTabGroups(state: LayoutState): Record<string, TabGroup> {
  return normalizeLayout(state).tabGroups ?? {};
}

export function getTabGroupLayout(state: LayoutState): TabGroupLayoutNode | null {
  return normalizeLayout(state).tabGroupLayout ?? null;
}

export function getFocusedGroupId(state: LayoutState): string | null {
  return normalizeLayout(state).focusedGroupId ?? null;
}

export function getGroupForTab(state: LayoutState, tabId: string): TabGroup | null {
  const normalized = normalizeLayout(state);
  return findGroupContainingTab(normalized.tabGroups ?? {}, tabId);
}

export function getTabsForGroup(state: LayoutState, groupId: string): WorkspaceTab[] {
  const normalized = normalizeLayout(state);
  const group = normalized.tabGroups?.[groupId];
  if (!group) return [];
  const byId = new Map(normalized.tabs.map((tab) => [tab.id, tab]));
  return group.tabIds.map((tabId) => byId.get(tabId)).filter((tab): tab is WorkspaceTab => Boolean(tab));
}

export function layoutReducer(inputState: LayoutState, action: LayoutAction): LayoutState {
  const state = normalizeLayout(inputState);
  switch (action.type) {
    case "ADD_TAB": {
      const exists = state.tabs.some((tab) => tab.id === action.tab.id);
      const tabs = exists ? state.tabs : [...state.tabs, action.tab];
      const layoutsByTabId = { ...state.layoutsByTabId };
      if (!layoutsByTabId[action.tab.id]) {
        const leafId = createLayoutId("leaf");
        const defaultSessionId = action.tab.kind === "browser" ? "" : action.tab.sessionId;
        const sessionId = action.sessionId ?? defaultSessionId;
        layoutsByTabId[action.tab.id] = {
          root: createLeafNode(leafId),
          activeLeafId: leafId,
          expandedLeafId: null,
          sessionIdsByLeafId: { [leafId]: sessionId },
        };
      }
      return normalizeLayoutInternal(
        {
          ...state,
          tabs,
          activeTabId: action.activate === false ? state.activeTabId : action.tab.id,
          layoutsByTabId,
        },
        true,
      );
    }
    case "CLOSE_TAB": {
      const closingIndex = state.tabs.findIndex((tab) => tab.id === action.tabId);
      if (closingIndex < 0) return state;

      let tabs = state.tabs.filter((tab) => tab.id !== action.tabId);
      const layoutsByTabId = { ...state.layoutsByTabId };
      delete layoutsByTabId[action.tabId];

      if (tabs.length === 0 && action.replacementTab) {
        tabs = [action.replacementTab];
        const leafId = "leaf-replacement";
        const defaultSessionId = action.replacementTab.kind === "browser" ? "" : action.replacementTab.sessionId;
        layoutsByTabId[action.replacementTab.id] = {
          root: createLeafNode(leafId),
          activeLeafId: leafId,
          expandedLeafId: null,
          sessionIdsByLeafId: { [leafId]: defaultSessionId },
        };
      }

      let activeTabId = state.activeTabId;
      if (state.activeTabId === action.tabId) {
        activeTabId = tabs[Math.min(closingIndex, tabs.length - 1)]?.id ?? null;
      }
      return normalizeLayoutInternal({ ...state, tabs, activeTabId, layoutsByTabId }, true);
    }
    case "ACTIVATE_TAB": {
      if (!state.tabs.some((tab) => tab.id === action.tabId)) return state;
      const group = findGroupContainingTab(state.tabGroups ?? {}, action.tabId);
      if (!group) return normalizeLayoutInternal({ ...state, activeTabId: action.tabId }, true);
      return normalizeLayoutInternal(
        {
          ...state,
          activeTabId: action.tabId,
          focusedGroupId: group.id,
          tabGroups: {
            ...state.tabGroups,
            [group.id]: { ...group, activeTabId: action.tabId },
          },
        },
        true,
      );
    }
    case "REORDER_TAB": {
      const group = findGroupContainingTab(state.tabGroups ?? {}, action.tabId);
      if (!group || group.tabIds.length < 2 || !Number.isFinite(action.targetIndex)) return state;
      const sourceIndex = group.tabIds.indexOf(action.tabId);
      const targetIndex = Math.max(0, Math.min(group.tabIds.length - 1, Math.trunc(action.targetIndex)));
      if (sourceIndex === targetIndex) return state;
      const tabIds = [...group.tabIds];
      const [moved] = tabIds.splice(sourceIndex, 1);
      tabIds.splice(targetIndex, 0, moved);
      return normalizeLayoutInternal(
        {
          ...state,
          tabGroups: {
            ...state.tabGroups,
            [group.id]: { ...group, tabIds },
          },
        },
        true,
      );
    }
    case "RENAME_TAB": {
      const label = action.label.trim();
      if (!label || !state.tabs.some((tab) => tab.id === action.tabId)) return state;
      return normalizeLayoutInternal(
        {
          ...state,
          tabs: state.tabs.map((tab) => (tab.id === action.tabId ? { ...tab, label } : tab)),
        },
        true,
      );
    }
    case "SET_TAB_PINNED": {
      if (!state.tabs.some((tab) => tab.id === action.tabId)) return state;
      return normalizeLayoutInternal(
        {
          ...state,
          tabs: state.tabs.map((tab) => (tab.id === action.tabId ? { ...tab, pinned: action.pinned } : tab)),
        },
        true,
      );
    }
    case "SPLIT_PANE": {
      const tabLayout = state.layoutsByTabId[action.tabId];
      if (!tabLayout) return state;
      const targetLeafId = action.targetLeafId ?? tabLayout.activeLeafId ?? findFirstLeafId(tabLayout.root);
      const existingLeafIds = collectLeafIds(tabLayout.root);
      if (!targetLeafId || !existingLeafIds.includes(targetLeafId)) return state;
      const newLeafId = action.newLeafId ?? createLayoutId("leaf");
      if (existingLeafIds.includes(newLeafId)) return state;
      const newRoot = splitLeaf(tabLayout.root, targetLeafId, newLeafId, action.direction, action.position, action.ratio);
      return normalizeLayoutInternal(
        {
          ...state,
          layoutsByTabId: {
            ...state.layoutsByTabId,
            [action.tabId]: {
              ...tabLayout,
              root: newRoot,
              activeLeafId: newLeafId,
              expandedLeafId: null,
              sessionIdsByLeafId: { ...tabLayout.sessionIdsByLeafId, [newLeafId]: action.sessionId },
            },
          },
        },
        true,
      );
    }
    case "MOVE_TAB_TO_GROUP": {
      const sourceTab = state.tabs.find((tab) => tab.id === action.sourceTabId);
      const groups = { ...(state.tabGroups ?? {}) };
      const sourceGroup = findGroupContainingTab(groups, action.sourceTabId);
      const targetGroup = groups[action.targetGroupId];
      if (!sourceTab || !sourceGroup || !targetGroup || !Number.isFinite(action.targetIndex ?? 0)) return state;

      if (sourceGroup.id === targetGroup.id) {
        if (action.targetIndex === undefined || sourceGroup.tabIds.length < 2) return state;
        const sourceIndex = sourceGroup.tabIds.indexOf(sourceTab.id);
        const targetIndex = Math.max(0, Math.min(sourceGroup.tabIds.length - 1, Math.trunc(action.targetIndex)));
        if (sourceIndex === targetIndex) return state;
        const tabIds = [...sourceGroup.tabIds];
        tabIds.splice(sourceIndex, 1);
        tabIds.splice(targetIndex, 0, sourceTab.id);
        groups[sourceGroup.id] = { ...sourceGroup, tabIds, activeTabId: sourceTab.id };
        return normalizeLayoutInternal(
          { ...state, activeTabId: sourceTab.id, focusedGroupId: sourceGroup.id, tabGroups: groups },
          true,
        );
      }

      const sourceIndex = sourceGroup.tabIds.indexOf(sourceTab.id);
      const remainingSourceTabIds = sourceGroup.tabIds.filter((tabId) => tabId !== sourceTab.id);
      let tabGroupLayout = state.tabGroupLayout ?? null;
      if (remainingSourceTabIds.length === 0) {
        delete groups[sourceGroup.id];
        tabGroupLayout = removeTabGroupLeaf(tabGroupLayout, sourceGroup.id);
      } else {
        groups[sourceGroup.id] = {
          ...sourceGroup,
          tabIds: remainingSourceTabIds,
          activeTabId:
            sourceGroup.activeTabId === sourceTab.id || !remainingSourceTabIds.includes(sourceGroup.activeTabId ?? "")
              ? remainingSourceTabIds[Math.min(sourceIndex, remainingSourceTabIds.length - 1)] ?? remainingSourceTabIds[0]
              : sourceGroup.activeTabId,
        };
      }

      const liveTarget = groups[targetGroup.id];
      if (!liveTarget) return state;
      const insertionIndex = Math.max(
        0,
        Math.min(liveTarget.tabIds.length, Math.trunc(action.targetIndex ?? liveTarget.tabIds.length)),
      );
      const targetTabIds = [...liveTarget.tabIds];
      targetTabIds.splice(insertionIndex, 0, sourceTab.id);
      groups[liveTarget.id] = { ...liveTarget, tabIds: targetTabIds, activeTabId: sourceTab.id };

      return normalizeLayoutInternal(
        {
          ...state,
          activeTabId: sourceTab.id,
          focusedGroupId: liveTarget.id,
          tabGroups: groups,
          tabGroupLayout,
        },
        true,
      );
    }
    case "MOVE_TAB_TO_SPLIT": {
      const sourceTab = state.tabs.find((tab) => tab.id === action.sourceTabId);
      const groups = { ...(state.tabGroups ?? {}) };
      const sourceGroup = findGroupContainingTab(groups, action.sourceTabId);
      const targetGroup = groups[action.targetGroupId];
      if (!sourceTab || !sourceGroup || !targetGroup) return state;
      if (sourceGroup.id === targetGroup.id && sourceGroup.tabIds.length <= 1) return state;

      const sourceIndex = sourceGroup.tabIds.indexOf(sourceTab.id);
      const remainingSourceTabIds = sourceGroup.tabIds.filter((tabId) => tabId !== sourceTab.id);
      const nextSourceActive =
        remainingSourceTabIds[Math.min(sourceIndex, remainingSourceTabIds.length - 1)] ?? remainingSourceTabIds[0] ?? null;

      let tabGroupLayout = state.tabGroupLayout ?? null;
      if (remainingSourceTabIds.length === 0 && sourceGroup.id !== targetGroup.id) {
        delete groups[sourceGroup.id];
        tabGroupLayout = removeTabGroupLeaf(tabGroupLayout, sourceGroup.id);
      } else {
        groups[sourceGroup.id] = {
          ...sourceGroup,
          tabIds: remainingSourceTabIds,
          activeTabId:
            sourceGroup.activeTabId === sourceTab.id || !remainingSourceTabIds.includes(sourceGroup.activeTabId ?? "")
              ? nextSourceActive
              : sourceGroup.activeTabId,
        };
      }

      const newGroupId = createLayoutId("group");
      groups[newGroupId] = { id: newGroupId, tabIds: [sourceTab.id], activeTabId: sourceTab.id };
      tabGroupLayout = splitTabGroupLeaf(
        tabGroupLayout,
        targetGroup.id,
        newGroupId,
        action.direction,
        action.position,
        action.ratio,
      );

      return normalizeLayoutInternal(
        {
          ...state,
          activeTabId: sourceTab.id,
          focusedGroupId: newGroupId,
          tabGroups: groups,
          tabGroupLayout,
        },
        true,
      );
    }
    case "DETACH_PANE_TO_TAB": {
      const sourceTab = state.tabs.find((tab) => tab.id === action.sourceTabId);
      const sourceLayout = state.layoutsByTabId[action.sourceTabId];
      const sourceGroup = findGroupContainingTab(state.tabGroups ?? {}, action.sourceTabId);
      if (
        !sourceTab ||
        sourceTab.kind === "browser" ||
        !sourceLayout ||
        !sourceGroup ||
        state.tabs.some((tab) => tab.id === action.newTab.id)
      ) {
        return state;
      }
      const leafIds = collectLeafIds(sourceLayout.root);
      if (leafIds.length <= 1 || !leafIds.includes(action.leafId)) return state;
      const movedSessionId = sourceLayout.sessionIdsByLeafId[action.leafId];
      if (!movedSessionId || action.newTab.kind === "browser") return state;

      const nextRoot = removeLeaf(sourceLayout.root, action.leafId);
      if (!nextRoot) return state;
      const fallbackLeafId = findSiblingLeafId(sourceLayout.root, action.leafId) ?? findFirstLeafId(nextRoot);
      const nextSessionIdsByLeafId = { ...sourceLayout.sessionIdsByLeafId };
      delete nextSessionIdsByLeafId[action.leafId];
      const nextPrimarySessionId =
        sourceTab.sessionId === movedSessionId
          ? nextSessionIdsByLeafId[fallbackLeafId] ?? Object.values(nextSessionIdsByLeafId)[0] ?? sourceTab.sessionId
          : sourceTab.sessionId;
      const nextSourceTab = { ...sourceTab, sessionId: nextPrimarySessionId };
      const newTab = { ...action.newTab, sessionId: movedSessionId };
      const targetGroupId = action.targetGroupId ?? sourceGroup.id;
      const targetGroup = state.tabGroups?.[targetGroupId];
      if (!targetGroup) return state;

      const groups = { ...(state.tabGroups ?? {}) };
      const liveTarget = groups[targetGroupId];
      const defaultIndex = targetGroupId === sourceGroup.id
        ? sourceGroup.tabIds.indexOf(sourceTab.id) + 1
        : liveTarget.tabIds.length;
      const insertionIndex = Math.max(
        0,
        Math.min(liveTarget.tabIds.length, Math.trunc(action.targetIndex ?? defaultIndex)),
      );
      const targetTabIds = [...liveTarget.tabIds];
      targetTabIds.splice(insertionIndex, 0, newTab.id);
      groups[targetGroupId] = { ...liveTarget, tabIds: targetTabIds, activeTabId: newTab.id };

      return normalizeLayoutInternal(
        {
          ...state,
          tabs: [...state.tabs.map((tab) => (tab.id === sourceTab.id ? nextSourceTab : tab)), newTab],
          activeTabId: newTab.id,
          focusedGroupId: targetGroupId,
          tabGroups: groups,
          layoutsByTabId: {
            ...state.layoutsByTabId,
            [sourceTab.id]: {
              ...sourceLayout,
              root: nextRoot,
              activeLeafId: sourceLayout.activeLeafId === action.leafId ? fallbackLeafId : sourceLayout.activeLeafId,
              expandedLeafId: sourceLayout.expandedLeafId === action.leafId ? null : sourceLayout.expandedLeafId,
              sessionIdsByLeafId: nextSessionIdsByLeafId,
            },
            [newTab.id]: {
              root: createLeafNode(action.leafId),
              activeLeafId: action.leafId,
              expandedLeafId: null,
              sessionIdsByLeafId: { [action.leafId]: movedSessionId },
            },
          },
        },
        true,
      );
    }
    case "SET_TAB_GROUP_RATIO": {
      if (!state.tabGroupLayout) return state;
      const nextLayout = setTabGroupRatioAtPath(state.tabGroupLayout, action.path, action.ratio);
      if (nextLayout === state.tabGroupLayout) return state;
      return normalizeLayoutInternal({ ...state, tabGroupLayout: nextLayout }, true);
    }
    case "CLOSE_PANE": {
      const tabLayout = state.layoutsByTabId[action.tabId];
      if (!tabLayout) return state;
      const leafIds = collectLeafIds(tabLayout.root);
      if (!leafIds.includes(action.leafId)) return state;
      const fallbackLeafId = findSiblingLeafId(tabLayout.root, action.leafId);
      const newRoot = removeLeaf(tabLayout.root, action.leafId);
      if (!newRoot) return layoutReducer(state, { type: "CLOSE_TAB", tabId: action.tabId });
      const newSessionIds = { ...tabLayout.sessionIdsByLeafId };
      delete newSessionIds[action.leafId];
      return normalizeLayoutInternal(
        {
          ...state,
          layoutsByTabId: {
            ...state.layoutsByTabId,
            [action.tabId]: {
              ...tabLayout,
              root: newRoot,
              activeLeafId:
                tabLayout.activeLeafId === action.leafId
                  ? fallbackLeafId ?? findFirstLeafId(newRoot)
                  : tabLayout.activeLeafId,
              expandedLeafId: tabLayout.expandedLeafId === action.leafId ? null : tabLayout.expandedLeafId,
              sessionIdsByLeafId: newSessionIds,
            },
          },
        },
        true,
      );
    }
    case "FOCUS_PANE": {
      const tabLayout = state.layoutsByTabId[action.tabId];
      if (!tabLayout || !collectLeafIds(tabLayout.root).includes(action.leafId)) return state;
      const group = findGroupContainingTab(state.tabGroups ?? {}, action.tabId);
      return normalizeLayoutInternal(
        {
          ...state,
          activeTabId: action.tabId,
          focusedGroupId: group?.id ?? state.focusedGroupId,
          tabGroups: group
            ? { ...state.tabGroups, [group.id]: { ...group, activeTabId: action.tabId } }
            : state.tabGroups,
          layoutsByTabId: {
            ...state.layoutsByTabId,
            [action.tabId]: { ...tabLayout, activeLeafId: action.leafId },
          },
        },
        true,
      );
    }
    case "SET_PANE_RATIO": {
      const tabLayout = state.layoutsByTabId[action.tabId];
      if (!tabLayout) return state;
      const root = setRatioAtPath(tabLayout.root, action.path, action.ratio);
      if (root === tabLayout.root) return state;
      return normalizeLayoutInternal(
        {
          ...state,
          layoutsByTabId: {
            ...state.layoutsByTabId,
            [action.tabId]: { ...tabLayout, root },
          },
        },
        true,
      );
    }
    case "SWAP_PANES": {
      const tabLayout = state.layoutsByTabId[action.tabId];
      if (!tabLayout) return state;
      const root = swapLeaves(tabLayout.root, action.sourceLeafId, action.targetLeafId);
      if (root === tabLayout.root) return state;
      return normalizeLayoutInternal(
        {
          ...state,
          layoutsByTabId: {
            ...state.layoutsByTabId,
            [action.tabId]: { ...tabLayout, root },
          },
        },
        true,
      );
    }
    case "TOGGLE_PANE_EXPANDED": {
      const tabLayout = state.layoutsByTabId[action.tabId];
      if (!tabLayout || !collectLeafIds(tabLayout.root).includes(action.leafId)) return state;
      return normalizeLayoutInternal(
        {
          ...state,
          layoutsByTabId: {
            ...state.layoutsByTabId,
            [action.tabId]: {
              ...tabLayout,
              expandedLeafId: tabLayout.expandedLeafId === action.leafId ? null : action.leafId,
            },
          },
        },
        true,
      );
    }
    case "EQUALIZE_PANES": {
      const tabLayout = state.layoutsByTabId[action.tabId];
      if (!tabLayout) return state;
      const root = equalizeRatios(tabLayout.root);
      if (root === tabLayout.root) return state;
      return normalizeLayoutInternal(
        {
          ...state,
          layoutsByTabId: {
            ...state.layoutsByTabId,
            [action.tabId]: { ...tabLayout, root },
          },
        },
        true,
      );
    }
  }
}

export function normalizeLayout(state: LayoutState): LayoutState {
  return normalizeLayoutInternal(state, false);
}

function normalizeLayoutInternal(state: LayoutState, force: boolean): LayoutState {
  if (!force && isNormalizedLayoutState(state)) return state;

  const dedupedTabs = dedupeTabs(state.tabs);
  if (dedupedTabs.length === 0) {
    if (
      state.tabs.length === 0 &&
      state.activeTabId === null &&
      Object.keys(state.layoutsByTabId).length === 0 &&
      state.tabGroupLayout === null &&
      state.focusedGroupId === null &&
      Object.keys(state.tabGroups ?? {}).length === 0
    ) {
      return state;
    }
    return {
      ...state,
      tabs: [],
      activeTabId: null,
      layoutsByTabId: {},
      tabGroups: {},
      tabGroupLayout: null,
      focusedGroupId: null,
    };
  }

  const validTabIds = new Set(dedupedTabs.map((tab) => tab.id));
  const nextLayoutsByTabId: Record<string, TabPaneLayout> = {};
  let paneLayoutsChanged = Object.keys(state.layoutsByTabId).length !== dedupedTabs.length;
  for (const tab of dedupedTabs) {
    const existing = state.layoutsByTabId[tab.id];
    if (existing) {
      const leaves = collectLeafIds(existing.root);
      const activeLeafId = leaves.includes(existing.activeLeafId ?? "") ? existing.activeLeafId : leaves[0] ?? null;
      const expandedLeafId = leaves.includes(existing.expandedLeafId ?? "") ? existing.expandedLeafId : null;
      const defaultSessionId = tab.kind === "browser" ? "" : tab.sessionId;
      const existingSessionKeys = Object.keys(existing.sessionIdsByLeafId);
      const mappingIsExact =
        existingSessionKeys.length === leaves.length &&
        leaves.every((leafId) => Object.prototype.hasOwnProperty.call(existing.sessionIdsByLeafId, leafId));
      if (activeLeafId === existing.activeLeafId && expandedLeafId === existing.expandedLeafId && mappingIsExact) {
        nextLayoutsByTabId[tab.id] = existing;
      } else {
        paneLayoutsChanged = true;
        nextLayoutsByTabId[tab.id] = {
          ...existing,
          activeLeafId,
          expandedLeafId,
          sessionIdsByLeafId: Object.fromEntries(
            leaves.map((leafId) => [leafId, existing.sessionIdsByLeafId[leafId] ?? defaultSessionId]),
          ),
        };
      }
    } else {
      paneLayoutsChanged = true;
      const leafId = createLayoutId("leaf-default");
      const defaultSessionId = tab.kind === "browser" ? "" : tab.sessionId;
      nextLayoutsByTabId[tab.id] = {
        root: createLeafNode(leafId),
        activeLeafId: leafId,
        expandedLeafId: null,
        sessionIdsByLeafId: { [leafId]: defaultSessionId },
      };
    }
  }
  const layoutsByTabId = paneLayoutsChanged ? nextLayoutsByTabId : state.layoutsByTabId;

  const incomingGroups = state.tabGroups ?? {};
  const groups: Record<string, TabGroup> = {};
  const assigned = new Set<string>();
  for (const [groupId, group] of Object.entries(incomingGroups)) {
    const tabIds = group.tabIds.filter((tabId) => validTabIds.has(tabId) && !assigned.has(tabId));
    if (tabIds.length === 0) continue;
    tabIds.forEach((tabId) => assigned.add(tabId));
    groups[groupId] = {
      id: groupId,
      tabIds,
      activeTabId: tabIds.includes(group.activeTabId ?? "") ? group.activeTabId : tabIds[0],
    };
  }

  let tabGroupLayout = pruneTabGroupLayout(state.tabGroupLayout ?? null, new Set(Object.keys(groups)));
  if (Object.keys(groups).length === 0) {
    const groupId = "group-default";
    groups[groupId] = {
      id: groupId,
      tabIds: dedupedTabs.map((tab) => tab.id),
      activeTabId: validTabIds.has(state.activeTabId ?? "") ? state.activeTabId : dedupedTabs[0].id,
    };
    dedupedTabs.forEach((tab) => assigned.add(tab.id));
    tabGroupLayout = { type: "group", groupId };
  }

  let focusedGroupId =
    state.focusedGroupId && groups[state.focusedGroupId]
      ? state.focusedGroupId
      : findGroupContainingTab(groups, state.activeTabId ?? "")?.id ?? findFirstTabGroupId(tabGroupLayout);
  if (!focusedGroupId || !groups[focusedGroupId]) focusedGroupId = Object.keys(groups)[0] ?? null;

  const unassigned = dedupedTabs.map((tab) => tab.id).filter((tabId) => !assigned.has(tabId));
  if (unassigned.length > 0 && focusedGroupId) {
    groups[focusedGroupId] = {
      ...groups[focusedGroupId],
      tabIds: [...groups[focusedGroupId].tabIds, ...unassigned],
    };
    unassigned.forEach((tabId) => assigned.add(tabId));
  }

  for (const groupId of Object.keys(groups)) {
    if (!containsTabGroup(tabGroupLayout, groupId)) {
      tabGroupLayout = appendTabGroupLayout(tabGroupLayout, { type: "group", groupId });
    }
  }
  tabGroupLayout = pruneTabGroupLayout(tabGroupLayout, new Set(Object.keys(groups)));

  if (focusedGroupId) {
    const focused = groups[focusedGroupId];
    if (focused && focused.tabIds.includes(state.activeTabId ?? "")) {
      groups[focusedGroupId] = { ...focused, activeTabId: state.activeTabId };
    }
  }

  const focusedGroup = focusedGroupId ? groups[focusedGroupId] : null;
  const activeTabId = focusedGroup?.activeTabId ?? dedupedTabs[0].id;
  const tabById = new Map(dedupedTabs.map((tab) => [tab.id, tab]));
  const flattenedIds = flattenTabIds(tabGroupLayout, groups);
  const tabs = flattenedIds.map((tabId) => tabById.get(tabId)).filter((tab): tab is WorkspaceTab => Boolean(tab));
  for (const tab of dedupedTabs) if (!flattenedIds.includes(tab.id)) tabs.push(tab);

  return {
    ...state,
    tabs,
    activeTabId,
    layoutsByTabId,
    tabGroups: groups,
    tabGroupLayout,
    focusedGroupId,
  };
}

function isNormalizedLayoutState(state: LayoutState): boolean {
  if (state.tabs.length === 0) {
    return (
      state.activeTabId === null &&
      Object.keys(state.layoutsByTabId).length === 0 &&
      state.tabGroupLayout === null &&
      state.focusedGroupId === null &&
      Object.keys(state.tabGroups ?? {}).length === 0
    );
  }
  if (!state.tabGroups || !state.tabGroupLayout || !state.focusedGroupId || !state.tabGroups[state.focusedGroupId]) return false;
  const valid = new Set(state.tabs.map((tab) => tab.id));
  const assigned = new Set<string>();
  for (const group of Object.values(state.tabGroups)) {
    if (group.tabIds.length === 0 || !containsTabGroup(state.tabGroupLayout, group.id)) return false;
    if (!group.activeTabId || !group.tabIds.includes(group.activeTabId)) return false;
    for (const tabId of group.tabIds) {
      if (!valid.has(tabId) || assigned.has(tabId)) return false;
      assigned.add(tabId);
    }
  }
  if (assigned.size !== valid.size) return false;
  return state.tabs.every((tab) => Boolean(state.layoutsByTabId[tab.id]));
}

function findGroupContainingTab(groups: Record<string, TabGroup>, tabId: string): TabGroup | null {
  if (!tabId) return null;
  return Object.values(groups).find((group) => group.tabIds.includes(tabId)) ?? null;
}

function splitTabGroupLeaf(
  root: TabGroupLayoutNode | null,
  targetGroupId: string,
  newGroupId: string,
  direction: PaneDirection,
  position: "first" | "second" = "second",
  ratio = 0.5,
): TabGroupLayoutNode | null {
  if (!root) return null;
  if (root.type === "group") {
    if (root.groupId !== targetGroupId) return root;
    const added: TabGroupLayoutNode = { type: "group", groupId: newGroupId };
    return {
      type: "split",
      direction,
      first: position === "first" ? added : root,
      second: position === "first" ? root : added,
      ratio: clampRatio(ratio),
    };
  }
  const first = splitTabGroupLeaf(root.first, targetGroupId, newGroupId, direction, position, ratio);
  if (first !== root.first) return { ...root, first: first ?? root.first };
  const second = splitTabGroupLeaf(root.second, targetGroupId, newGroupId, direction, position, ratio);
  if (second !== root.second) return { ...root, second: second ?? root.second };
  return root;
}

function removeTabGroupLeaf(root: TabGroupLayoutNode | null, groupId: string): TabGroupLayoutNode | null {
  if (!root) return null;
  if (root.type === "group") return root.groupId === groupId ? null : root;
  const first = removeTabGroupLeaf(root.first, groupId);
  if (!first) return root.second;
  if (first !== root.first) return { ...root, first };
  const second = removeTabGroupLeaf(root.second, groupId);
  if (!second) return root.first;
  if (second !== root.second) return { ...root, second };
  return root;
}

function pruneTabGroupLayout(root: TabGroupLayoutNode | null, validGroupIds: Set<string>): TabGroupLayoutNode | null {
  if (!root) return null;
  if (root.type === "group") return validGroupIds.has(root.groupId) ? root : null;
  const first = pruneTabGroupLayout(root.first, validGroupIds);
  const second = pruneTabGroupLayout(root.second, validGroupIds);
  if (!first) return second;
  if (!second) return first;
  if (first === root.first && second === root.second) return root;
  return { ...root, first, second };
}

function appendTabGroupLayout(first: TabGroupLayoutNode | null, second: TabGroupLayoutNode): TabGroupLayoutNode {
  if (!first) return second;
  return { type: "split", direction: "horizontal", first, second, ratio: 0.5 };
}

function containsTabGroup(root: TabGroupLayoutNode | null, groupId: string): boolean {
  if (!root) return false;
  if (root.type === "group") return root.groupId === groupId;
  return containsTabGroup(root.first, groupId) || containsTabGroup(root.second, groupId);
}

function findFirstTabGroupId(root: TabGroupLayoutNode | null): string | null {
  if (!root) return null;
  let node = root;
  while (node.type === "split") node = node.first;
  return node.groupId;
}

function flattenTabIds(root: TabGroupLayoutNode | null, groups: Record<string, TabGroup>): string[] {
  if (!root) return [];
  if (root.type === "group") return groups[root.groupId]?.tabIds ?? [];
  return [...flattenTabIds(root.first, groups), ...flattenTabIds(root.second, groups)];
}

function setTabGroupRatioAtPath(root: TabGroupLayoutNode, path: string, ratio: number): TabGroupLayoutNode {
  const segments = path.split(".").filter(Boolean);
  const visit = (node: TabGroupLayoutNode, remaining: string[]): TabGroupLayoutNode => {
    if (node.type === "group") return node;
    if (remaining.length === 0) {
      const nextRatio = clampRatio(ratio);
      return node.ratio === nextRatio ? node : { ...node, ratio: nextRatio };
    }
    const [head, ...rest] = remaining;
    if (head !== "first" && head !== "second") return node;
    const child = visit(node[head], rest);
    return child === node[head] ? node : { ...node, [head]: child };
  };
  return visit(root, segments);
}

function dedupeTabs(tabs: WorkspaceTab[]) {
  const seen = new Set<string>();
  return tabs.filter((tab) => {
    if (seen.has(tab.id)) return false;
    seen.add(tab.id);
    return true;
  });
}

function createLayoutId(prefix: string) {
  const randomPart = globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `${prefix}:${randomPart}`;
}

import { createLayoutState, normalizeLayout } from "../state/layout";
import { collectLeafIds, createLeafNode } from "../state/paneTree";
import type { WorkspaceState } from "../state/workspaceStore";
import { loadBrowserSettings } from "./browserSettings";
import {
  worktreeIdentity,
  type BrowserTab,
  type LayoutState,
  type PersistedLayout,
  type PersistedTab,
  type PersistedTerminalSession,
  type PersistedWorkspace,
  type PersistedWorkspaceSession,
  type PersistedWorktree,
  type TabGroup,
  type TerminalSession,
  type TerminalTab,
  type WorkspaceTab,
  type Worktree,
} from "./types";

export const WORKSPACE_SESSION_VERSION = 2;

export function serializeWorkspaceState(
  workspaceId: string,
  repoRoot: string,
  state: WorkspaceState,
  existingSession?: PersistedWorkspaceSession | null,
): PersistedWorkspaceSession {
  const browserSettings = loadBrowserSettings();
  const restoreBrowserTabs = browserSettings.restoreTabsOnLaunch;

  const persistedWorktrees: PersistedWorktree[] = state.worktrees.map((wt) => ({
    path: wt.path,
    branch: wt.branch ?? "",
    head: wt.head,
    isMain: !wt.branch || wt.branch === "main" || wt.branch === "master",
    isLocked: Boolean(wt.locked),
  }));

  function serializeLayout(layoutState: LayoutState): PersistedLayout {
    const normalizedLayout = normalizeLayout(layoutState);
    const persistedTabs: PersistedTab[] = [];
    for (const tab of normalizedLayout.tabs) {
      if (tab.kind === "browser") {
        if (!restoreBrowserTabs) continue;
        persistedTabs.push({
          id: tab.id,
          kind: "browser",
          label: tab.label,
          pinned: Boolean(tab.pinned),
          browser: {
            browserId: tab.browserId,
            url: tab.url,
            title: tab.title ?? null,
            loading: tab.loading,
            canGoBack: tab.canGoBack,
            canGoForward: tab.canGoForward,
            profileId: tab.profileId,
            worktreePath: tab.worktreePath,
            worktreeLabel: tab.worktreeLabel,
          },
        });
        continue;
      }

      const tabLayout = normalizedLayout.layoutsByTabId[tab.id];
      persistedTabs.push({
        id: tab.id,
        kind: "terminal",
        label: tab.label,
        pinned: Boolean(tab.pinned),
        terminal: tabLayout
          ? {
              primarySessionId: tab.sessionId,
              paneTree: tabLayout.root,
              sessionIdsByLeafId: { ...tabLayout.sessionIdsByLeafId },
              activeLeafId: tabLayout.activeLeafId,
              expandedLeafId: tabLayout.expandedLeafId,
            }
          : {
              primarySessionId: tab.sessionId,
              paneTree: createLeafNode(`leaf-persisted:${tab.id}`),
              sessionIdsByLeafId: { [`leaf-persisted:${tab.id}`]: tab.sessionId },
              activeLeafId: `leaf-persisted:${tab.id}`,
              expandedLeafId: null,
            },
      });
    }

    const tabIds = new Set(persistedTabs.map((t) => t.id));
    const activeTabId =
      normalizedLayout.activeTabId && tabIds.has(normalizedLayout.activeTabId)
        ? normalizedLayout.activeTabId
        : (persistedTabs[0]?.id ?? null);
    const primaryTabId =
      normalizedLayout.primaryTabId && tabIds.has(normalizedLayout.primaryTabId)
        ? normalizedLayout.primaryTabId
        : (persistedTabs[0]?.id ?? null);

    return {
      splitMode: normalizedLayout.split ?? "none",
      primaryTabId,
      secondaryTabId: normalizedLayout.secondaryTabId ?? null,
      activeTabId,
      tabs: persistedTabs,
      tabGroups: Object.values(normalizedLayout.tabGroups ?? {}).map((group) => ({
        id: group.id,
        tabIds: group.tabIds.filter((id) => tabIds.has(id)),
        activeTabId: group.activeTabId && tabIds.has(group.activeTabId) ? group.activeTabId : null,
      })),
      tabGroupLayout: normalizedLayout.tabGroupLayout ?? null,
      focusedGroupId: normalizedLayout.focusedGroupId ?? null,
    };
  }

  const persistedLayout = serializeLayout(state.layout);
  const persistedWorktreeLayouts: Record<string, PersistedLayout> = {};
  for (const [wtPath, layout] of Object.entries(state.worktreeLayouts ?? {})) {
    if (layout) {
      persistedWorktreeLayouts[wtPath] = serializeLayout(layout);
    }
  }

  const allPersistedLayouts = [persistedLayout, ...Object.values(persistedWorktreeLayouts)];
  const referencedSessionIds = new Set<string>();
  for (const layout of allPersistedLayouts) {
    for (const tab of layout.tabs) {
      if (tab.kind === "browser") continue;
      const terminal = tab.terminal;
      if (terminal?.primarySessionId) referencedSessionIds.add(terminal.primarySessionId);
      for (const sessionId of Object.values(terminal?.sessionIdsByLeafId ?? {})) {
        if (sessionId) referencedSessionIds.add(sessionId);
      }
    }
  }

  const persistedTerminalSessions: Record<string, PersistedTerminalSession> = {};
  const createdAt = Date.now();
  for (const [id, sess] of Object.entries(state.sessions)) {
    if (!sess || !referencedSessionIds.has(id)) continue;
    persistedTerminalSessions[id] = {
      localSessionId: sess.id,
      backendSessionId: sess.backendSessionId,
      worktreePath: sess.worktreePath ?? sess.cwd,
      cwd: sess.cwd,
      createdAt,
    };
  }

  const workspace: PersistedWorkspace = {
    workspaceId,
    repoRoot,
    worktrees: persistedWorktrees,
    activeWorktreePath: state.activeWorktreePath,
    layout: persistedLayout,
    ...(Object.keys(persistedWorktreeLayouts).length > 0 ? { worktreeLayouts: persistedWorktreeLayouts } : {}),
    terminalSessions: persistedTerminalSessions,
  };

  const workspaces = {
    ...(existingSession?.workspaces ?? {}),
    [workspaceId]: workspace,
  };

  return {
    version: WORKSPACE_SESSION_VERSION,
    timestamp: Date.now(),
    activeWorkspaceId: workspaceId,
    workspaces,
  };
}

export function deserializeWorkspaceState(
  workspaceId: string,
  persistedSession: PersistedWorkspaceSession,
  liveBackendSessionIds?: Iterable<string> | null,
): WorkspaceState | null {
  const ws = persistedSession.workspaces?.[workspaceId];
  if (!ws) return null;
  const isV2 = (persistedSession.version ?? 1) >= 2;

  const browserSettings = loadBrowserSettings();
  const restoreBrowser = browserSettings.restoreTabsOnLaunch;
  const knownProfiles = new Set(browserSettings.profiles.map((p) => p.id));
  const fallbackProfileId = browserSettings.defaultProfileId;

  const liveSet = liveBackendSessionIds
    ? (liveBackendSessionIds instanceof Set ? liveBackendSessionIds : new Set(liveBackendSessionIds))
    : null;

  const worktrees: Worktree[] = (ws.worktrees || []).map((wt) => ({
    path: wt.path,
    branch: wt.branch ? (wt.branch.startsWith("refs/heads/") ? wt.branch : `refs/heads/${wt.branch}`) : null,
    head: wt.head,
    bare: false,
    detached: false,
    locked: wt.isLocked ? "locked" : null,
    prunable: null,
  }));

  const sessions: Record<string, TerminalSession> = {};
  for (const [mapKey, sess] of Object.entries(ws.terminalSessions || {})) {
    const localSessionId = sess.localSessionId || mapKey || sess.sessionId || "";
    if (!localSessionId) continue;
    const persistedBackendSessionId = isV2 ? (sess.backendSessionId ?? null) : (sess.backendSessionId ?? sess.sessionId ?? null);
    const backendSessionId = liveSet
      ? (persistedBackendSessionId && liveSet.has(persistedBackendSessionId) ? persistedBackendSessionId : null)
      : persistedBackendSessionId;
    const worktreePath = sess.worktreePath || sess.cwd;
    const matchingWorktree = worktrees.find((wt) => wt.path === worktreePath);
    sessions[localSessionId] = {
      id: localSessionId,
      cwd: sess.cwd || worktreePath,
      worktreePath,
      workspaceId,
      worktree: matchingWorktree ? worktreeIdentity(matchingWorktree) : null,
      backendSessionId,
      lifecycle: backendSessionId ? "working" : "exited",
    };
  }

  function deserializeLayout(persistedLayout: PersistedLayout | undefined): LayoutState {
    if (!persistedLayout) return createLayoutState();

    const tabs: WorkspaceTab[] = [];
    for (const persistedTab of persistedLayout.tabs || []) {
      if (persistedTab.kind === "browser" || persistedTab.browser) {
        if (!restoreBrowser) continue;
        const browser = persistedTab.browser;
        const rawProfileId = browser?.profileId;
        const profileId = rawProfileId && knownProfiles.has(rawProfileId) ? rawProfileId : fallbackProfileId;
        const tab: BrowserTab = {
          id: persistedTab.id,
          kind: "browser",
          label: persistedTab.label,
          browserId: browser?.browserId ?? persistedTab.sessionId ?? `restored-browser:${persistedTab.id}`,
          url: browser?.url ?? "about:blank",
          title: browser?.title ?? persistedTab.label,
          canGoBack: browser?.canGoBack ?? false,
          canGoForward: browser?.canGoForward ?? false,
          loading: browser?.loading ?? false,
          pinned: Boolean(persistedTab.pinned),
          profileId,
          worktreePath: browser?.worktreePath ?? persistedTab.worktreePath,
          worktreeLabel: browser?.worktreeLabel,
        };
        tabs.push(tab);
        continue;
      }

      const primarySessionId = persistedTab.terminal?.primarySessionId ?? persistedTab.sessionId ?? "";
      const tab: TerminalTab = {
        id: persistedTab.id,
        kind: "terminal",
        sessionId: primarySessionId,
        label: persistedTab.label,
        pinned: Boolean(persistedTab.pinned),
      };
      tabs.push(tab);
    }

    const layoutsByTabId: LayoutState["layoutsByTabId"] = {};
    for (const persistedTab of persistedLayout.tabs || []) {
      if (persistedTab.kind === "browser" || persistedTab.browser) {
        if (!restoreBrowser) continue;
        const leafId = `leaf-browser:${persistedTab.id}`;
        layoutsByTabId[persistedTab.id] = {
          root: createLeafNode(leafId),
          activeLeafId: leafId,
          expandedLeafId: null,
          sessionIdsByLeafId: { [leafId]: "" },
        };
        continue;
      }

      const terminal = persistedTab.terminal;
      const legacyTabLayout = persistedLayout.layoutsByTabId?.[persistedTab.id];
      const paneTree = terminal?.paneTree ?? persistedTab.paneTree ?? legacyTabLayout?.root;
      const primarySessionId = terminal?.primarySessionId ?? persistedTab.sessionId ?? "";
      const root = paneTree ?? createLeafNode(`leaf-restored:${persistedTab.id}`);
      const leafIds = collectLeafIds(root);
      const persistedMapping =
        terminal?.sessionIdsByLeafId ?? persistedTab.sessionIdsByLeafId ?? legacyTabLayout?.sessionIdsByLeafId;
      const sessionIdsByLeafId = persistedMapping && Object.keys(persistedMapping).length > 0
        ? Object.fromEntries(leafIds.map((leafId) => [leafId, persistedMapping[leafId] ?? primarySessionId]))
        : Object.fromEntries(leafIds.map((leafId) => [leafId, primarySessionId]));
      const requestedActiveLeafId =
        terminal?.activeLeafId ?? persistedTab.activeLeafId ?? legacyTabLayout?.activeLeafId ?? null;
      const requestedExpandedLeafId =
        terminal?.expandedLeafId ?? persistedTab.expandedLeafId ?? legacyTabLayout?.expandedLeafId ?? null;
      layoutsByTabId[persistedTab.id] = {
        root,
        activeLeafId: requestedActiveLeafId && leafIds.includes(requestedActiveLeafId) ? requestedActiveLeafId : leafIds[0] ?? null,
        expandedLeafId:
          requestedExpandedLeafId && leafIds.includes(requestedExpandedLeafId) ? requestedExpandedLeafId : null,
        sessionIdsByLeafId,
      };
    }

    const tabGroups: Record<string, TabGroup> | undefined = persistedLayout.tabGroups?.length
      ? Object.fromEntries(
          persistedLayout.tabGroups.map((group) => [
            group.id,
            { id: group.id, tabIds: [...group.tabIds], activeTabId: group.activeTabId },
          ]),
        )
      : undefined;

    return normalizeLayout({
      tabs,
      primaryTabId: persistedLayout.primaryTabId || (tabs[0]?.id ?? null),
      secondaryTabId: persistedLayout.secondaryTabId || null,
      activeTabId: persistedLayout.activeTabId || (tabs[0]?.id ?? null),
      split: (persistedLayout.splitMode as LayoutState["split"]) || "none",
      nestedSplit: null,
      layoutsByTabId,
      tabGroups,
      tabGroupLayout: persistedLayout.tabGroupLayout ?? null,
      focusedGroupId: persistedLayout.focusedGroupId ?? null,
    });
  }

  const activeLayout = deserializeLayout(ws.layout);
  const worktreeLayouts: Record<string, LayoutState> = {};
  if (ws.worktreeLayouts) {
    for (const [wtPath, persistedWtLayout] of Object.entries(ws.worktreeLayouts)) {
      if (persistedWtLayout) {
        worktreeLayouts[wtPath] = deserializeLayout(persistedWtLayout);
      }
    }
  }

  const allLayouts = [activeLayout, ...Object.values(worktreeLayouts)];
  const referencedSessionIds = new Set<string>();
  for (const layout of allLayouts) {
    for (const tab of layout.tabs) {
      if (tab.kind === "browser") continue;
      if (tab.sessionId) referencedSessionIds.add(tab.sessionId);
      const tabLayout = layout.layoutsByTabId[tab.id];
      for (const sessionId of Object.values(tabLayout?.sessionIdsByLeafId ?? {})) {
        if (sessionId) referencedSessionIds.add(sessionId);
      }
    }
  }

  const referencedSessions = Object.fromEntries(
    Object.entries(sessions).filter(([sessionId]) => referencedSessionIds.has(sessionId)),
  );

  return {
    worktrees,
    activeWorktreePath: ws.activeWorktreePath || (worktrees[0]?.path ?? null),
    sessions: referencedSessions,
    layout: activeLayout,
    worktreeLayouts,
    unreadTabIds: {},
    unreadWorktreePaths: {},
    activityBySessionId: {},
  };
}

import { useRef, useEffect } from "react";
import { setBrowserBounds, setBrowserVisible } from "../lib/browserTauri";
import { BrowserToolbar } from "./BrowserToolbar";
import type { BrowserTab } from "../lib/types";

interface BrowserPaneProps {
  tab: BrowserTab;
  visible?: boolean;
  onNavigate: (url: string) => void;
  onReload: () => void;
}

export function BrowserPane({ tab, visible = true, onNavigate, onReload }: BrowserPaneProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    const updateVisibility = (nextVisible: boolean) => {
      void setBrowserVisible(tab.browserId, nextVisible).catch(() => undefined);
    };

    const updateBounds = () => {
      if (!visible) {
        updateVisibility(false);
        return;
      }

      const rect = el.getBoundingClientRect();
      void setBrowserBounds(tab.browserId, {
        x: rect.x,
        y: rect.y,
        width: rect.width,
        height: rect.height,
      }).catch(() => undefined);
      updateVisibility(true);
    };

    updateBounds();

    const resizeObserver = new ResizeObserver(() => {
      updateBounds();
    });

    resizeObserver.observe(el);
    window.addEventListener("resize", updateBounds);

    return () => {
      resizeObserver.disconnect();
      window.removeEventListener("resize", updateBounds);
      // Native child webviews outlive React DOM nodes; cleanup also covers Fast Refresh remounts.
      updateVisibility(false);
    };
  }, [tab.browserId, visible]);

  return (
    <div className="flex flex-col w-full h-full bg-background overflow-hidden">
      <BrowserToolbar tab={tab} onNavigate={onNavigate} onReload={onReload} />
      <div
        ref={containerRef}
        data-testid="browser-viewport"
        className="flex-1 w-full bg-card relative"
      />
    </div>
  );
}

